<?php
/**
 * Public Header Component
 *
 * Renders the top navigation bar for every public page. The header
 * contains the brand link, the primary navigation, the language
 * switcher, and the authentication buttons.
 *
 * CORRECTIONS (Version 11.0):
 * - Added the language switcher. The switcher is generated by
 *   getLanguageSwitcherHtml() from Solution/includes/i18n.php and
 *   appears next to the authentication buttons.
 * - Replaced every hardcoded string with a __() call. The header now
 *   renders in English or Afrikaans depending on the active language.
 * - Added a "Signed in with Google" indicator on the header for users
 *   whose session was established through Google SSO. The indicator
 *   reads from getAuthProvider() in Solution/includes/auth.php.
 * - Retains the CSRF meta tag, the security header call, the active
 *   page highlighting, the mobile menu toggle, and the role-specific
 *   dashboard and cart links.
 *
 * SOURCE: NOTES - Make use of SSO. Include multi-language support for
 *         at least two South African languages: English and Afrikaans.
 *
 * @version 11.0
 */

require_once dirname(__DIR__) . '/config/constants.php';
require_once dirname(__DIR__) . '/includes/auth.php';
require_once dirname(__DIR__) . '/includes/i18n.php';

// Set security headers for this public page.
setSecurityHeaders();

// Determine the current page for active-state highlighting.
$currentPage = basename($_SERVER['PHP_SELF']);

// Get the CSRF token if a session is active.
$csrfToken = '';

if (session_status() === PHP_SESSION_ACTIVE)
{
    $csrfToken = getCsrfToken();
}

// The provider label is shown next to the user name when the session
// was established through Google SSO.
$authProvider = function_exists('getAuthProvider') ? getAuthProvider() : null;
?>
