                        <a href="<?php echo escapeOutput(ROOT_URL); ?>/about.php"
                           class="<?php echo isActivePublicPage('about.php', $currentPage); ?>">
                            <?php echo __e('nav.about'); ?>
                        </a>
                    </li>
                    <li>
                        <a href="<?php echo escapeOutput(ROOT_URL); ?>/index.php#vendors">
                            <?php echo __e('nav.services'); ?>
